def lis(arr):
    ends = {}
    longest = 0

    for i, val in enumerate(arr):

        if longest == 0:
            ends[0] = i
            longest = 1

        else:
            prefix_lengths = [j for j in range(1, longest + 1) if arr[ends[j]] < val]

            length = max(prefix_lengths) if prefix_lengths else 0

            if length == longest or val < arr[ends[longest]]:
                ends[longest + 1] = i
                longest = longest + 1

    return longest

print(lis([]))
print(lis([3]))
print(lis([10, 20, 11, 32, 22, 48, 43]))
